import {retrieveKnowledge,sources} from './knowledge.js';
import {knowledgeChunks} from './knowledge-data.js';
import {openVoice} from './voice-ui.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const display=(text,retrieval)=>String(text).replace(/\bF\d{2}\b/g,id=>{const at=retrieval.chunks.findIndex(c=>c.id===id);return at<0?id:'资料'+(at+1);});
const examples=['增肌一定要每组力竭吗？','重量没变，次数多了算进步吗？','完整行程和半程怎么理解？','增肌饮食为什么还要看碳水？'];
export function mountKnowledge(root){
 let question='',retrieval=null,answer=null,consent=false,busy=false,error='',controller=null,alive=true;
 const render=()=>{
  if(!alive)return;
  root.innerHTML=`<div class="page-heading"><div><p class="eyebrow">LEARN WITH EVIDENCE</p><h1>练得明白一点。</h1><p class="sub">先找到资料，再回答问题。每条结论都可以回看出处。</p></div></div><div class="knowledge-layout"><section class="panel knowledge-input"><label for="knowledge-question">你想了解什么？</label><textarea id="knowledge-question" rows="3" maxlength="600" placeholder="例如：增肌一定要每组力竭吗？" ${busy?'disabled':''}>${esc(question)}</textarea><div class="knowledge-actions"><button class="secondary" data-k="voice" ${busy?'disabled':''}>语音输入</button><span class="muted">一般增肌知识 · 最多 600 字</span></div><div class="knowledge-examples">${examples.map((s,i)=>`<button data-k="example" data-i="${i}" ${busy?'disabled':''}>${esc(s)}</button>`).join('')}</div><button class="primary" data-k="retrieve" ${busy||!question.trim()?'disabled':''}>查找资料</button><p class="sub">查资料在本机完成，不调用模型，不发送训练记录。</p>${retrieval?`<div class="knowledge-service"><span class="chip">DeepSeek · 资料问答</span><p class="sub">根据下方资料回答，保留来源与适用条件。</p><label class="review-consent"><input id="knowledge-consent" type="checkbox" ${consent?'checked':''} ${busy?'disabled':''}>同意将本次问题与下方资料发送至 DeepSeek。 不发送训练历史，不加入训练集。</label><button class="primary" data-k="answer" ${busy||!consent||!retrieval.chunks.length?'disabled':''}>${busy?'正在根据资料回答…':'根据资料回答'}</button></div>`:''}<p class="validation" role="status">${esc(error)}</p></section><div class="knowledge-results" aria-live="polite">${answer?`<section class="panel knowledge-answer"><span class="chip">DeepSeek · 基于本次资料</span><h2>${answer.status==='answered'?'给你的参考':'这次资料还不够'}</h2>${answer.points.map(p=>`<p>${esc(display(p.text,retrieval))} <span class="knowledge-refs">${p.sourceIds.map(id=>`<a href="#fact-${esc(id)}" aria-label="查看资料 ${retrieval.chunks.findIndex(c=>c.id===id)+1}">[${retrieval.chunks.findIndex(c=>c.id===id)+1}]</a>`).join(' ')}</span></p>`).join('')}<p class="sub">${esc(display(answer.limitation,retrieval))}</p><small class="muted">AI 可能误读资料，请结合下方来源与适用范围理解。</small></section>`:''}${retrieval?`<section class="panel knowledge-evidence"><div class="section-head"><h2>${retrieval.chunks.length?'找到的资料':'当前资料范围'}</h2><span class="chip">${retrieval.chunks.length} 条</span></div><p class="sub">${esc(retrieval.message)}</p>${retrieval.chunks.map((c,index)=>`<article id="fact-${c.id}"><span class="eyebrow">参考资料 ${index+1}</span><h3>${esc(c.title)}</h3><p>${esc(c.text)}</p><p class="sub">适用范围：${esc(c.scope)}</p><details class="knowledge-provenance"><summary>来源与资料说明</summary><p class="sub">${c.sources.some(id=>sources[id].type==='产品规范')?'包含产品统计约定，请与研究证据区分。':'AI 整理的简短资料摘要，可回看原始出处。'}</p>${c.unsupportedInferences?.length?`<p class="sub">不能据此推断：${c.unsupportedInferences.map(esc).join('；')}。</p>`:''}<div class="knowledge-sources">${c.sources.map(id=>{const s=sources[id];return `<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.title)} ↗</a><small class="muted">${s.year?esc(s.year)+' · ':''}${s.readStatus==='unavailable_on_this_review_attempt'?'本次未能重新访问，保留历史来源':s.readStatus==='product_specification'?'产品记录口径':'公开摘要／资料整理'}${s.accessedAt?' · 核对尝试 '+esc(s.accessedAt):''}</small>`;}).join('')}</div></details></article>`).join('')}</section>`:`<section class="panel knowledge-empty"><span class="knowledge-mark" aria-hidden="true">↗</span><h2>把“听说”变成有出处。</h2><p>从负荷、行程到饮食和进步观察，从一个小问题开始。</p><p class="sub">资料选自 ACSM、公开研究与 NIH。现有 ${knowledgeChunks.length} 条简短资料，覆盖常见增肌问题；未覆盖时会说明资料不足。</p></section>`}</div></div>`;
  root.querySelector('#knowledge-question').oninput=e=>{question=e.target.value;retrieval=null;answer=null;consent=false;error='';root.querySelector('[data-k="retrieve"]').disabled=!question.trim();root.querySelector('.knowledge-service')?.remove();root.querySelector('.knowledge-results').innerHTML='<p class="sub">问题已更改，请重新查找资料。</p>';};
  const checkbox=root.querySelector('#knowledge-consent');if(checkbox)checkbox.onchange=e=>{consent=e.target.checked;root.querySelector('[data-k="answer"]').disabled=!consent||busy||!retrieval.chunks.length;};
 };
 const setQuestion=text=>{question=text.slice(0,600);retrieval=null;answer=null;consent=false;error='';render();};
 root.onclick=async e=>{
  const b=e.target.closest('[data-k]');if(!b||b.disabled)return;
  if(b.dataset.k==='voice')return openVoice({onAccept:setQuestion,maxLength:600});
  if(b.dataset.k==='example')return setQuestion(examples[Number(b.dataset.i)]);
  if(b.dataset.k==='retrieve'){try{retrieval=retrieveKnowledge(question);answer=null;consent=false;error='';}catch(e){error=e.message;}return render();}
  if(b.dataset.k==='answer'){
   busy=true;error='';answer=null;controller=new AbortController();const timer=setTimeout(()=>controller.abort(),35000);render();
   try{const r=await fetch('/api/ai/knowledge',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question,consent:true}),signal:controller.signal});const v=await r.json();if(!r.ok)throw Error(v.error||'暂时无法回答，请稍后重试。');if(alive){answer=v.result;retrieval=v.retrieval;}}
   catch(e){if(alive)error=e.name==='AbortError'?'这次回答超时，问题和资料已保留。':e instanceof TypeError?'网络暂不可用，仍可直接阅读资料。':e.message;}
   finally{clearTimeout(timer);busy=false;render();}
  }
 };
 render();return ()=>{alive=false;controller?.abort();};
}
